changeSet.sql:
create or alter procedure [graph].[Hop_GetLineage] @hopSalt varchar(25), @direction char(1), -- (F)orward, (B)ackward @hopNumber int, @revealCheckNeeded bit, @leafOnly bit as begin set nocount on;
declare @maxRowId int = 0;
-- Backward-facing hop if @direction = 'B' begin insert into #links ([Uid], Direction, HopNumber, ProvidedKey, [Key], ID, AssetUid, [Segment], PredicateId, PredicateUid, PredicateType, [Predicate]) select E.[Uid], @direction, @hopNumber, A.[Key],
utility.GetHash(@hopSalt + '|' + cast(S.ID as varchar(50))), S.ID as ToID, S.Uid as ToUid, S.Segments as ToSegment,
E.PredicateID, E.PredicateUid, E.PredicateType, P.Name from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #hopAssets A where MATCH(S-(E)->T) and E.PredicateType in (1,12,13) and P.[Uid] = E.PredicateUid and T.ID = A.ID and A.HopNumber = @hopNumber-1 and A.Direction = 'B' and E.Uid not in (select Uid from #relationsToIgnore); end else if @direction = 'F' -- Forward-facing hop begin insert into #links ([Uid], Direction, HopNumber, ProvidedKey, [Key], ID, AssetUid, [Segment], PredicateId, PredicateUid, PredicateType, [Predicate]) select E.[Uid], @direction, @hopNumber, A.[Key],
utility.GetHash(@hopSalt + '|' + cast(T.ID as varchar(50))), T.ID as ToID, T.Uid as ToUid, T.Segments as ToSegment,
E.PredicateID, E.PredicateUid, E.PredicateType, P.Name from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #hopAssets A where MATCH(S-(E)->T) and E.PredicateType in (1,12,13) and P.[Uid] = E.PredicateUid and S.ID = A.ID and A.HopNumber = @hopNumber-1 and A.Direction = 'F' and E.Uid not in (select Uid from #relationsToIgnore); end;
select @maxRowId = max(RowID) from #nodes;
if @maxRowId is null begin set @maxRowId = -1 end
exec graph.Hop_LoadHopHierarchies @hopSalt, @direction, @hopNumber; exec graph.Hop_LoadSingleParentHeirarchies @hopSalt, @direction, @hopNumber;
-- This indicates which assets will be used for subsequent hops, as well as which direction. exec graph.Hop_LoadNextHopAssets @direction, @hopNumber, @maxRowId, @leafOnly
-- Calculate reveal. if @revealCheckNeeded = 1 begin if @direction = 'B' begin update R set R.Reveal = case when S.[Count] > 0 then 2 else 0 end from #nodes R inner join #hopAssets H on H.[Key] = R.[Key] and H.HopNumber = @hopNumber and H.Direction = @direction cross apply ( select count(1) as [Count] from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T where MATCH(S-(E)->T) and E.PredicateType in (1,12,13) and E.Uid not in (select Uid from #relationsToIgnore) and T.ID = R.AssetID ) S where R.Parsed = 0; end
if @direction = 'F' begin update R set R.Reveal = case when S.[Count] > 0 then 1 else 0 end from #nodes R inner join #hopAssets H on H.[Key] = R.[Key] and H.HopNumber = @hopNumber and H.Direction = @direction cross apply ( select count(1) as [Count] from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T where MATCH(S-(E)->T) and E.PredicateType in (1,12,13) and E.Uid not in (select Uid from #relationsToIgnore) and S.ID = R.AssetID ) S where R.Parsed = 0 and R.Reveal = 0; end end else begin update #nodes set Reveal = 0 where Parsed = 0; end end

changeSet.rollback:
create or alter procedure [graph].[Hop_GetLineage] @hopSalt varchar(25), @direction char(1), -- (F)orward, (B)ackward @hopNumber int, @revealCheckNeeded bit, @leafOnly bit as begin set nocount on;
declare @maxRowId int = 0;
-- Backward-facing hop if @direction = 'B' begin insert into #links ([Uid], Direction, HopNumber, ProvidedKey, [Key], ID, AssetUid, [Path], [Segment], PredicateId, PredicateUid, PredicateType, [Predicate]) select E.[Uid], @direction, @hopNumber, A.[Key],
utility.GetHash(@hopSalt + '|' + cast(S.ID as varchar(50))), S.ID as ToID, S.Uid as ToUid, S.[Path] as ToPath, S.Segments as ToSegment,
E.PredicateID, E.PredicateUid, E.PredicateType, P.Name from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #hopAssets A where MATCH(S-(E)->T) and E.PredicateType in (1,12,13) and P.[Uid] = E.PredicateUid and T.ID = A.ID and A.HopNumber = @hopNumber-1 and A.Direction = 'B' and E.Uid not in (select Uid from #relationsToIgnore); end else if @direction = 'F' -- Forward-facing hop begin insert into #links ([Uid], Direction, HopNumber, ProvidedKey, [Key], ID, AssetUid, [Path], [Segment], PredicateId, PredicateUid, PredicateType, [Predicate]) select E.[Uid], @direction, @hopNumber, A.[Key],
utility.GetHash(@hopSalt + '|' + cast(T.ID as varchar(50))), T.ID as ToID, T.Uid as ToUid, T.[Path] as ToPath, T.Segments as ToSegment,
E.PredicateID, E.PredicateUid, E.PredicateType, P.Name from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #hopAssets A where MATCH(S-(E)->T) and E.PredicateType in (1,12,13) and P.[Uid] = E.PredicateUid and S.ID = A.ID and A.HopNumber = @hopNumber-1 and A.Direction = 'F' and E.Uid not in (select Uid from #relationsToIgnore); end;
select @maxRowId = max(RowID) from #nodes;
if @maxRowId is null begin set @maxRowId = -1 end
exec graph.Hop_LoadHopHierarchies @hopSalt, @direction, @hopNumber; exec graph.Hop_LoadSingleParentHeirarchies @hopSalt, @direction, @hopNumber;
-- This indicates which assets will be used for subsequent hops, as well as which direction. exec graph.Hop_LoadNextHopAssets @direction, @hopNumber, @maxRowId, @leafOnly
-- Calculate reveal. if @revealCheckNeeded = 1 begin if @direction = 'B' begin update R set R.Reveal = case when S.[Count] > 0 then 2 else 0 end from #nodes R inner join #hopAssets H on H.[Key] = R.[Key] and H.HopNumber = @hopNumber and H.Direction = @direction cross apply ( select count(1) as [Count] from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T where MATCH(S-(E)->T) and E.PredicateType in (1,12,13) and E.Uid not in (select Uid from #relationsToIgnore) and T.ID = R.AssetID ) S where R.Parsed = 0; end
if @direction = 'F' begin update R set R.Reveal = case when S.[Count] > 0 then 1 else 0 end from #nodes R inner join #hopAssets H on H.[Key] = R.[Key] and H.HopNumber = @hopNumber and H.Direction = @direction cross apply ( select count(1) as [Count] from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T where MATCH(S-(E)->T) and E.PredicateType in (1,12,13) and E.Uid not in (select Uid from #relationsToIgnore) and S.ID = R.AssetID ) S where R.Parsed = 0 and R.Reveal = 0; end end else begin update #nodes set Reveal = 0 where Parsed = 0; end end
